var ids=['projects','projects--empty','project','recent','artifacts','artifacts--empty','artifacts--detail','routines','routines--new','customize','customize--profile'];['Light/Clean','Dark/Clean'].forEach(function(app){var p=doc.pages.find(function(p){return p.name==='Proto macOS '+app.split('/')[0];});ids.forEach(function(id){var matches=p.layers.filter(function(l){return l.name==='Screen/macos/'+app+'/'+id;}),s=matches[0],borders=[],badLinks=[],dots=[],fonts=[];function walk(l,path){path=path+'/'+l.name;if(l.style&&(l.style.borders||[]).some(function(b){return b.enabled;})&&l.name.indexOf('traffic-')!==0)borders.push(path);if(l.name.indexOf('link:')===0&&/ \d+$/.test(l.name))badLinks.push(l.name);if(l.name==='dot')dots.push(l.frame.width);if(l.type==='Text'&&fonts.indexOf(l.style.fontFamily)<0)fonts.push(l.style.fontFamily);(l.layers||[]).forEach(function(c){walk(c,path);});}walk(s,'');console.log(JSON.stringify({app:app,id:id,frame:s.id,count:matches.length,page:p.name,w:s.frame.width,h:s.frame.height,x:s.frame.x,y:s.frame.y,borders:borders,badLinks:badLinks,dots:dots,fonts:fonts}));});});